const FRAME_ROWS = ['idle', 'walk', 'attack', 'cast', 'hurt']
// A sprite that shows the AI's frames: the animation's progress t (0..1) picks one of its frames. `anims`
// lists each animation's frame indexes (any count); without it the frames are equal rows in FRAME_ROWS order.
// The pose is ignored, so nothing is cut or bent. mouth / emit / glows are on the bitmap grid.
function FRAME_SPRITE(id, rig, extra = {}) {
  const src = FRAME_BMP[id],
    per = src.frames.length / FRAME_ROWS.length,
    anims =
      src.anims ||
      Object.fromEntries(
        FRAME_ROWS.map((n, r) => [n, [...Array(per).keys()].map((k) => r * per + k)])
      ),
    w = src.frames[0][0].length,
    h = src.frames[0].length,
    size = Math.ceil((Math.max(w, h) + 6) / 8) * 8,
    ox = Math.round((size - w) / 2),
    oy = size - h - 2,
    at = ([x, y]) => [x + ox, y + oy],
    bmps = src.frames.map((rows) => ({ pal: src.pal, rows }))
  return {
    ...extra,
    size,
    rig,
    draw(s, P, name = 'idle', t = 0) {
      const list = anims[name] || anims.idle
      s.bmp(bmps[list[Math.min(list.length - 1, Math.floor(t * list.length))]], ox, oy)
    },
    mouth: extra.mouth ? at(extra.mouth) : [size / 2, size / 2],
    emit: (extra.emit || []).map((e) => ({ ...e, x: e.x + ox, y: e.y + oy })),
    glows: (extra.glows || []).map(([x, y, ...g]) => [x + ox, y + oy, ...g]),
  }
}
